const api = $json;
const norm = $("Normalize LinkedIn Lead").item.json;
const messages = Array.isArray(api.messages) ? api.messages : [];
const first = messages[0] || {};
const research = api.research || {};
const person = research.person || {};
const company = research.company || {};
const warnings = api.warnings || {};
const categories = Array.isArray(warnings.categories) ? warnings.categories : [];
const str = (v) => (v === undefined || v === null) ? "" : String(v);
const linkedin_url = str((person && person.linkedin_profile_url) || norm.linkedin_url || "");
const linkedin_line = linkedin_url ? (":link:  <" + linkedin_url + "|LinkedIn profile>") : "";
const handleName = () => {
  const m = linkedin_url.match(/linkedin\.com\/in\/([^/?#]+)/i);
  if (!m) return "";
  let h = decodeURIComponent(m[1]).replace(/-[0-9a-f]{6,}$/i, "").replace(/[-_]+/g, " ").trim();
  if (!h) return "";
  return h.split(" ").filter(Boolean).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
};
const person_name = str(person.name) || str(norm.name) || handleName() || "there";
const intro_text = str(first.message);
const sequence_preview = messages.map((m) => str(m.message)).join("\n\n--------\n\n");
const followups = messages.slice(1);
const followups_preview = followups.map((m) => str(m.message)).join("\n\n--------\n\n");
const warning_line =
  warnings && warnings.has_warnings
    ? ":warning:  *Warnings:* " +
      ((categories || []).join(", ") || "flagged") +
      (warnings.summary ? "  —  " + warnings.summary : "")
    : "";
return {
  intro_text: intro_text,
  sequence_preview: sequence_preview || "No messages returned.",
  followups_preview: followups_preview,
  followups_count: followups.length,
  step_count: messages.length,
  person_name: person_name,
  person_title: str(person.title),
  company_name: str(company.name) || str(norm.company),
  linkedin_url: linkedin_url,
  linkedin_line: linkedin_line,
  signal: str(norm.signal),
  link: str(api.link),
  warning_line: warning_line,
  warnings_summary: str(warnings.summary)
};

